<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Application\Usecase\RevokeToken;

use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenRevocationGateway;
use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenSigner;

class RevokeTokenUsecase
{
    public function __construct(
        private readonly TokenRevocationGateway $revocationGateway,
        private readonly TokenSigner $tokenSigner
    ) {
    }

    /**
     * Revokes a token per RFC 7009.
     * Silently ignores invalid, unparseable, or foreign-client tokens.
     */
    public function revoke(string $tokenValue, string $clientId, string $tenant): void
    {
        $payload = $this->tokenSigner->parseSignedPayload($tenant, $tokenValue);
        if ($payload === null) {
            return;
        }

        $jti = $payload['jti'] ?? null;
        if ($jti === null || $jti === '') {
            return;
        }

        // Only the client that issued the token may revoke it
        $tokenClientId = $payload['azp'] ?? null;
        if ($tokenClientId !== $clientId) {
            return;
        }

        $exp = $payload['exp'] ?? (time() + 3600);
        $expiresAt = new \DateTimeImmutable('@' . $exp);

        // Refresh tokens carry scope as an array containing 'refresh'
        $scope = $payload['scope'] ?? null;
        $tokenType = (is_array($scope) && in_array('refresh', $scope, true)) ? 'refresh' : 'access';

        $this->revocationGateway->revokeJti($jti, $tenant, $tokenType, $expiresAt);
    }
}
